Code for Part 2 example:

# Input instructions and create dataframe with direction and amount of spin
# Also, we want the number of times around the dial and the actual change
# in location on the dial.
import_instructions &lt;- function(input_file) {
  data_in &lt;- read_lines(here::here("data", input_file)) |&gt;
    tibble(value = _)
  data_in |&gt;
    mutate(direction = str_sub(value, 1, 1),
           total_amount = as.integer(str_sub(value, 2)),
           full_spin_count = floor(total_amount / 100),
           mod_amount = total_amount %% 100,
           shift  = if_else(direction == "L", mod_amount, -mod_amount)
           )
}

# Step through the instructions and spin the dial as directed.
# Count the number of times we stop at zero OR pass through zero.
determine_result &lt;- function() {
  count_zeros &lt;- 0
  for (i in seq_len(nrow(data_calc))) {
    start_dial &lt;- dial[1]
    dial &lt;- shift(dial, n = data_calc$shift[i], type = "cyclic")
    end_dial &lt;- dial[1]

    if (data_calc$direction[i] == "L") {
      if (start_dial != 0 && end_dial != 0 && start_dial - end_dial &lt; 0) { count_zeros &lt;- count_zeros + 1  }
      }
    else {
      if (start_dial != 0 && end_dial != 0 && start_dial - end_dial &gt; 0) { count_zeros &lt;- count_zeros + 1  }
    }
    if (end_dial == 0) {count_zeros &lt;- count_zeros + 1}
    count_zeros &lt;- count_zeros + data_calc$full_spin_count[i]
  }
  result &lt;- count_zeros
}

data_calc &lt;- import_instructions("day01_example.txt")
dial &lt;- create_dial(0, 99, 50)
result &lt;- determine_result()

